"""Run tests"""
import argparse
import json
import logging
import os
from pathlib import Path
from typing import Dict, List
from tqdm import tqdm
from test_runner import find_json_files, write_results_to_csv
from test_runner.test_case import TestCaseGroup, json_to_test_case
from test_runner.vanguard import check_circom2llvm_exists, \
    check_vanguard_driver_exists, run_vanguard_driver_on_test_case_group

logger = logging.getLogger(__package__)

TEST_OPTIONS = ["vanguard", "circom"]

def _setup_logging(log_level: str):
    """Set up logging (generated by chatGPT, and then modified)

    Args:
        log_level (str): the log level
    """
    handler = logging.StreamHandler()
    handler.setLevel(log_level)
    formatter = logging.Formatter(
        "[%(levelname)-7s] %(message)s (%(filename)s:%(lineno)d)"
    )
    handler.setFormatter(formatter)
    logger.setLevel(log_level)
    logger.addHandler(handler)

def process_arguments():
    """
    Process the command-line arguments using argparse.

    Returns:
        A tuple containing the directory and keyword values.
    """
    parser = argparse.ArgumentParser(description="Run tests in directory")
    parser.add_argument("directory", type=str, help="Path to the directory")
    parser.add_argument("driver", choices=TEST_OPTIONS, help=f"Keyword ({TEST_OPTIONS})")
    parser.add_argument("--log-level", choices=["DEBUG", "INFO", "WARNING"], default="INFO", dest="log_level")

    args = parser.parse_args()

    # Validate the directory argument
    directory = args.directory
    if not os.path.isdir(directory):
        parser.error(f"The directory '{directory}' does not exist.")

    _setup_logging(log_level=args.log_level)

    return directory, args.driver

def print_summary(results: List[Dict[str, str]]):
    num_success = len(list(filter(lambda r: "success" in r and bool(r["success"]), results)))
    print(f"""Summary:
Tests Run        : {len(results)}
Tests with Errors: {num_success}
""")

def main():
    """Run the tests in the directory
    """
    (directory, driver) = process_arguments()
    if driver == "vanguard":
        if not check_circom2llvm_exists():
            raise ValueError("Cannot find circom2llvm executable. Did you run nix develop '.?submodules=1#withCircom' in Vanguard?")
        if not check_vanguard_driver_exists():
            raise ValueError("Cannot find vanguard_driver executable. Are you in the nix shell?")
        def process(test_case_group: TestCaseGroup) -> List[Dict[str, str]]:
            return run_vanguard_driver_on_test_case_group(test_case_group)
    elif driver == "circom":
        raise NotImplementedError
    else:
        assert driver not in TEST_OPTIONS

    test_case_groups: List[TestCaseGroup] = []
    for json_file in find_json_files(directory):
        # pylint: disable=W1514
        with open(json_file) as file:
            json_data = json.load(file)
            test_case_group: TestCaseGroup = json_to_test_case(Path(json_file), json_data)
            test_case_groups.append(test_case_group)

    groups_with_prog_bar = None
    if not logger.isEnabledFor(logging.DEBUG):
        groups_with_prog_bar = tqdm(test_case_groups, desc='Processing tests')
    else:
        groups_with_prog_bar = test_case_groups

    results: List[Dict[str, str]] = []
    for test_case_group in groups_with_prog_bar:
        results += process(test_case_group)

    for result in results:
        if "group_dir" in result:
            result["group_dir"] = str(Path(result["group_dir"]).relative_to(directory))

    output_file = str(Path("test_results.csv").absolute())
    logger.info("Writing results to %s", output_file)
    write_results_to_csv(results, output_file=output_file)
    print_summary(results)


if __name__ == '__main__':
    main()
